.grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  border-top: 1px solid #eef0f4;
  border-left: 1px solid #eef0f4;
  border-radius: 10px;
  overflow: hidden;
  background: #ffffff;
}

.cell {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 106px;
  padding: 8px 8px 9px;
  border: 0;
  border-right: 1px solid #eef0f4;
  border-bottom: 1px solid #eef0f4;
  background: #ffffff;
  color: var(--text-secondary);
  text-align: left;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
  transition: background 140ms ease;
}

.weekend {
  background: #fcfcfd;
}

.cell:hover {
  background: #f8fafc;
}

.cell:focus-visible {
  z-index: 1;
  outline: 2px solid #64748b;
  outline-offset: -2px;
}

.todayCell {
  background: #fdfefe;
}

.selected {
  z-index: 1;
  background: #f6f9fc;
  box-shadow: inset 0 0 0 1.5px #475569;
}

.selected:hover {
  background: #f2f6fb;
}

.outside {
  background: #fafbfc;
  color: var(--text-muted);
}

.outside .number {
  opacity: 0.36;
}

.cellHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  width: 100%;
  min-height: 22px;
  margin-bottom: 6px;
}

.number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 4px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  color: #1e293b;
  letter-spacing: -0.01em;
}

.weekend .number {
  color: #64748b;
}

.today {
  background: #111827;
  color: #ffffff !important;
  font-weight: 600;
}

.moreBadge {
  display: inline-flex;
  align-items: center;
  height: 16px;
  padding: 0 5px;
  border-radius: 999px;
  background: #f1f4f8;
  color: #64748b;
  font-size: 9.5px;
  font-weight: 550;
  line-height: 1;
}

.items {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  width: 100%;
}

.item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 1.5px 2px;
  border-radius: 4px;
  font-size: 11px;
  line-height: 1.4;
  color: #334155;
}

.item::before {
  content: '';
  width: 2.5px;
  height: 11px;
  border-radius: 999px;
  flex-shrink: 0;
}

.itemText {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  min-width: 0;
}

.todo::before {
  background: #7c9bc4;
}

.schedule::before {
  background: #a98bb8;
}

.study::before {
  background: #6fa398;
}

.record::before {
  background: #c7a667;
}

.expense {
  color: #7c5144;
}

.expense::before {
  background: #c88773;
}

.more {
  padding: 1px 2px;
  font-size: 9.5px;
  color: var(--text-muted);
}

