import type { DailyDaySummary } from '../../types/dailyEvent';

export interface CalendarCellMetric {
  id: 'todo' | 'finance' | 'record' | 'token';
  label: string;
  value: string;
  title: string;
}

export function formatCompactMoney(amount: number): string {
  if (!Number.isFinite(amount) || amount <= 0) return '0';
  const rounded = Math.round(amount * 100) / 100;
  if (Number.isInteger(rounded)) return String(rounded);
  return rounded.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
}

export function formatCompactChars(chars: number): string {
  if (!Number.isFinite(chars) || chars <= 0) return '0字';
  if (chars >= 10000) {
    const wan = Math.round((chars / 10000) * 10) / 10;
    return `${wan}万字`;
  }
  return `${Math.round(chars)}字`;
}

export function formatCompactTokens(tokens: number): string {
  if (!Number.isFinite(tokens) || tokens <= 0) return '0';
  if (tokens >= 1_000_000) {
    const millions = Math.round((tokens / 1_000_000) * 10) / 10;
    return `${millions}M`;
  }
  if (tokens >= 10_000) {
    const thousands = Math.round((tokens / 1_000) * 10) / 10;
    return `${thousands}K`;
  }
  return String(Math.round(tokens));
}

/** 构造月历单格极简核心指标：待办、财务、资料累计与 Token 消耗。 */
export function calendarCellMetrics(
  summary: DailyDaySummary | undefined,
  recordCount: number,
  recordChars: number,
  tokenTotal: number,
): CalendarCellMetric[] {
  const metrics: CalendarCellMetric[] = [];

  if (summary && summary.todoCount > 0) {
    metrics.push({
      id: 'todo',
      label: '待办',
      value: `${summary.completedTodoCount}/${summary.todoCount}`,
      title: `待办：已完成 ${summary.completedTodoCount} / 共 ${summary.todoCount}`,
    });
  }

  const income = summary?.incomeTotal ?? 0;
  const expense = summary?.expenseTotal ?? 0;
  if (income > 0 || expense > 0) {
    const formatted = `${formatCompactMoney(income)}/${formatCompactMoney(expense)}元`;
    metrics.push({
      id: 'finance',
      label: '财务',
      value: formatted,
      title: `财务：收入 ¥${income.toFixed(2)} / 支出 ¥${expense.toFixed(2)}`,
    });
  }

  if (recordChars > 0 || recordCount > 0) {
    const value = recordChars > 0 ? formatCompactChars(recordChars) : `${recordCount}篇`;
    metrics.push({
      id: 'record',
      label: '资料',
      value,
      title: recordChars > 0
        ? `资料累计：${Math.round(recordChars)}字（${recordCount}篇）`
        : `资料累计：${recordCount}篇`,
    });
  }

  if (tokenTotal > 0) {
    metrics.push({
      id: 'token',
      label: 'Token',
      value: formatCompactTokens(tokenTotal),
      title: `Token 累计消耗：${Math.round(tokenTotal).toLocaleString()}`,
    });
  }

  return metrics;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
  calendarCellMetrics,
  formatCompactChars,
  formatCompactMoney,
  formatCompactTokens,
} from './calendarMetrics.ts';

test('月历单格核心指标格式化与过滤零值', () => {
  const metrics = calendarCellMetrics(
    {
      date: '2026-11-20',
      eventCount: 5,
      todoCount: 4,
      completedTodoCount: 3,
      scheduleCount: 0,
      expenseTotal: 12,
      incomeTotal: 30,
      headline: '',
    },
    2,
    1200,
    1_000_000,
  );

  assert.deepEqual(
    metrics.map((m) => [m.label, m.value]),
    [
      ['待办', '3/4'],
      ['财务', '30/12元'],
      ['资料', '1200字'],
      ['Token', '1M'],
    ],
  );
});

test('无数据日期不输出零值指标，且兼容旧后端缺失字数与收入字段', () => {
  assert.deepEqual(calendarCellMetrics(undefined, 0, 0, 0), []);
  const fallback = calendarCellMetrics(
    {
      date: '2026-11-18',
      eventCount: 1,
      todoCount: 0,
      completedTodoCount: 0,
      scheduleCount: 0,
      expenseTotal: 27.5,
      headline: '',
    },
    1,
    0,
    4820,
  );
  assert.deepEqual(
    fallback.map((m) => [m.label, m.value]),
    [
      ['财务', '0/27.5元'],
      ['资料', '1篇'],
      ['Token', '4820'],
    ],
  );
  assert.equal(formatCompactMoney(30.0), '30');
  assert.equal(formatCompactMoney(27.5), '27.5');
  assert.equal(formatCompactChars(12500), '1.3万字');
  assert.equal(formatCompactTokens(25400), '25.4K');
});

import type { DailyDaySummary } from '../../types/dailyEvent';
import { calendarCellMetrics } from '../../features/calendar/calendarMetrics';
import { Skeleton } from '../common/Skeleton';
import styles from './CalendarDateCell.module.css';

interface Props {
  date: Date;
  dateKey: string;
  inMonth: boolean;
  today: boolean;
  selected: boolean;
  available: boolean;
  loading?: boolean;
  previewOpen: boolean;
  summary?: DailyDaySummary;
  recordCount?: number;
  recordChars?: number;
  tokenTotal?: number;
  onSelect: () => void;
  onPreview: (anchor: HTMLButtonElement, immediate: boolean) => void;
  onLeave: () => void;
}

/** 极简无边框圆角日期面块：顶部居中日期数字，下方展示当日核心量化指标。 */
export function CalendarDateCell({
  date,
  dateKey,
  inMonth,
  today,
  selected,
  available,
  loading = false,
  previewOpen,
  summary,
  recordCount = 0,
  recordChars = 0,
  tokenTotal = 0,
  onSelect,
  onPreview,
  onLeave,
}: Props) {
  const metrics = calendarCellMetrics(summary, recordCount, recordChars, tokenTotal);
  const hasData = inMonth && !loading && metrics.length > 0;

  return (
    <button
      type="button"
      className={[
        styles.cell,
        !inMonth ? styles.outside : '',
        hasData ? styles.hasData : '',
        selected ? styles.selected : '',
      ].filter(Boolean).join(' ')}
      onMouseEnter={(event) => onPreview(event.currentTarget, false)}
      onMouseLeave={onLeave}
      onFocus={(event) => {
        if (event.currentTarget.matches(':focus-visible'))
          onPreview(event.currentTarget, true);
      }}
      onBlur={onLeave}
      onClick={onSelect}
      aria-pressed={selected}
      aria-current={today ? 'date' : undefined}
      aria-expanded={previewOpen}
      aria-controls={previewOpen ? 'calendar-day-preview' : undefined}
      aria-label={
        loading
          ? `${dateKey}，正在读取摘要`
          : `${dateKey}，${metrics.map((metric) => metric.title).join('，') || '暂无记录'}${!available ? '，部分摘要暂不可用' : ''}`
      }
    >
      <span className={`${styles.number} ${today ? styles.today : ''}`}>
        {date.getDate()}
      </span>
      {inMonth && (
        <span className={styles.metrics}>
          {loading ? (
            <Skeleton variant="text" decorative />
          ) : (
            <>
              {metrics.map((metric) => (
                <span key={metric.id} className={styles.metricRow} title={metric.title}>
                  <span className={styles.metricLabel}>{metric.label}</span>
                  <span className={styles.metricValue}>{metric.value}</span>
                </span>
              ))}
              {!available && <span className={styles.unavailable}>部分摘要暂不可用</span>}
            </>
          )}
        </span>
      )}
    </button>
  );
}

