2: import { createPortal } from 'react-dom';
3: import { CalendarDayDetails } from './CalendarDayDetails';
4: import styles from './CalendarDayPreview.module.css';
5: interface CalendarDayPreviewProps {
6:   date: Date;
7:   id: string;
8:   anchor: HTMLElement;
9:   onEnter: () => void;
10:   onLeave: () => void;
11:   onClose: () => void;
12: }
13: /** 单个浮层容器，异步详情不改变定位方向。 */
14: export function CalendarDayPreview({
15:   date,
16:   id,
17:   anchor,
18:   onEnter,
19:   onLeave,
20:   onClose,
21: }: CalendarDayPreviewProps) {
22:   const panel = useRef<HTMLDivElement>(null);
23:   const [position, setPosition] = useState({ left: 0, top: 0 });
24:   useLayoutEffect(() => {
25:     const place = () => {
26:       const rect = anchor.getBoundingClientRect();
27:       // 按面板上限预留空间，异步内容加载后不翻转方向，避免悬停跳动。
28:       const height = Math.min(360, window.innerHeight - 24);
29:       const width = panel.current?.offsetWidth ?? 320;
30:       // 优先放在日期侧边，保留可直接移入的短间隙；内容变化不改变锚点。
31:       const right = rect.right + 6;
32:       const left = rect.left - width - 6;
33:       const beside = right + width <= window.innerWidth - 12 || left >= 12;
34:       setPosition({
35:         left: beside
36:           ? right + width <= window.innerWidth - 12
37:             ? right
38:             : left
39:           : Math.max(12, Math.min(rect.left, window.innerWidth - width - 12)),
40:         top: beside
41:           ? Math.max(12, Math.min(rect.top, window.innerHeight - height - 12))
42:           : Math.max(
43:               12,
44:               Math.min(rect.bottom + 6, window.innerHeight - height - 12),
45:             ),
46:       });
47:     };
48:     place();
49:     window.addEventListener('resize', place);
50:     window.addEventListener('scroll', place, true);
51:     return () => {
52:       window.removeEventListener('resize', place);
53:       window.removeEventListener('scroll', place, true);
54:     };
55:   }, [anchor]);
56:   useEffect(() => {
57:     const dismiss = (event: KeyboardEvent) => {
58:       if (event.key === 'Escape') onClose();
59:     };
60:     document.addEventListener('keydown', dismiss);
61:     return () => document.removeEventListener('keydown', dismiss);
62:   }, [onClose]);
63:   return createPortal(
64:     <div
65:       ref={panel}
66:       id={id}
67:       role="region"
68:       aria-label="每日详情"
69:       tabIndex={0}
70:       className={styles.preview}
71:       style={position}
72:       onMouseEnter={onEnter}
73:       onMouseLeave={onLeave}
74:       onFocus={onEnter}
75:       onBlur={(event) => {
76:         if (!event.currentTarget.contains(event.relatedTarget)) onLeave();
77:       }}
78:     >
79:       <header className={styles.heading}>
80:         <div>
81:           <strong>
82:             {date.getMonth() + 1}月{date.getDate()}日 · 星期
83:             {'日一二三四五六'[date.getDay()]}
84:           </strong>
85:           <small>当天记录</small>
86:         </div>
87:         <button type="button" onClick={onClose} aria-label="关闭每日详情">
88:           ×
89:         </button>
90:       </header>
91:       <CalendarDayDetails date={date} compact />
92:     </div>,
93:     document.body,
94:   );
95: }

