  font-variant-numeric: tabular-nums;
}

.expenseVal {
  color: #a64b43;
}

.incomeVal {
  color: #2d7a5b;
}

.zeroVal {
  color: var(--text-secondary, #4b5563);
}

.compact .section {
  border-radius: 8px;
}

.summaryTrigger {
  list-style: none;
