  border-radius: 8px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary, #111827);
  transition: background 140ms ease;
}

.summaryTrigger::-webkit-details-marker {
  display: none;
}

.summaryTrigger:hover {
  background: #f5f7fa;
}

.summaryTrigger:focus-visible {
  outline: 2px solid var(--accent-blue, #7ebefb);
  outline-offset: -1px;
}

.summaryTitle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.chevron {
  color: var(--text-muted, #9ca3af);
  transition: transform 150ms ease;
  flex-shrink: 0;
}

